# overwrite transform based on the demos: inward projections from each colored bar are zero rays; markers become 4.
code='''def transform(grid):
    out=[row[:] for row in grid]; h=len(out); w=len(out[0])
    # bars are monochrome runs at opposite edges; project 0 inward in their columns
    for c in range(w):
        if grid[0][c]==1:
            for r in range(1,h):
                if grid[r][c]==1: break
                out[r][c]=0
        if grid[h-1][c]==1:
            for r in range(h-2,-1,-1):
                if grid[r][c]==1: break
                out[r][c]=0
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0: out[r][c]=4
    return out
'''
p.write_text(code); exec(compile(code,str(p),'exec'),globals()); print(transform(grid))
